-- Hành trình khủng long: 5 scenarios + 60 characters (plan 2026-10-26)
insert into public.game_scenarios (id, game, seq, title, inspiration, story, setting, stages, class_plan, asset_ids,
  rounds, minutes_per_round, character_count, active, plan_version)
select e->>0, 'dino_journey', (e->>1)::smallint, e->>2, e->>3, e->>4, e->>5, e->6, e->7,
  array(select jsonb_array_elements_text(e->8)), 6, 5, 12, true, 2
from jsonb_array_elements($j$[["dino-01",1,"Quả Trứng Trên Đồng Cỏ","Mở đầu saga: khủng long con nở ra, tập đi, học nhận biết đồng cỏ cùng cha (phim hoạt hình sinh tồn nhẹ nhàng, không bạo lực).","Sáng nay, quả trứng cuối cùng của bầy bắt đầu nứt. Bố Gruk đứng canh bên tổ, cô Đuôi Dài và cả bầy nín thở chờ. Chú khủng long con Mốc chui ra, ngơ ngác nhìn đồng cỏ lần đầu tiên. Mỗi chặng, Mốc học một điều để sống: đứng vững, nhận ra cha, gọi tên bạn cùng bầy, uống nước an toàn, biết tiếng gầm nào là báo động. Mỗi vật phát sáng trên đồng cỏ chứa một câu hỏi, đúng thì Mốc làm được việc đó. Hoàng hôn xuống, Mốc phải chạy một mình về tổ trước khi trời tối. Cha đứng ở cuối đường, và đó là lần đầu Mốc nghe cha gọi tên mình.","Đồng cỏ xanh trải dài lúc rạng đông, sương còn đọng trên ngọn cỏ cao. Quả trứng nằm trong tổ lót lá bên túp da cổ, quanh đó là hồ nước nhỏ, hàng cọ và những tảng đá phủ rêu. Xa xa là cao nguyên đỏ.",[{"n":1,"title":"Quả trứng nứt","minutes":5,"optional":false,"goal":"Giúp Mốc phá vỏ trứng và chui ra khỏi tổ.","beats":["Mỗi câu đúng làm vỏ trứng nứt thêm một đường.","Bố Gruk đỡ nhẹ vỏ trứng, bầy đứng quanh nhìn."],"question_hook":"Chạm vào vật thể đang phát sáng trên đồng cỏ (dấu chân, vũng nước, bụi cỏ, quả trứng...) để mở câu hỏi nhỏ ngay cạnh nó; đúng thì khủng long con làm được việc đó (ngửi, vồ, uống, trốn, gầm), sai thì cha nhắc lại sau 5 giây, không trừ điểm nặng. Quả trứng sáng lên mỗi khi bạn đứng cạnh.","reward":"Mốc nở ra và có tên.","vocab":["egg","crack","baby","nest","shell"],"assets":["dino_nest_shelter","tree_nursery_pot","wood_plank_a","ground_grass_patch","mushrooms","hdri_dawn"],"subtitles":[{"en":"The egg is starting to crack.","vi":"Có tiếng nứt! quả trứng đang nứt ra.","parts":["Có tiếng nứt! ",["egg","quả trứng",0]," đang ",["crack","nứt ra",1],"."]},{"en":"Welcome, little one! You have a warm nest.","vi":"Chào bé con! Mẹ thiên nhiên cho con một tổ ấm.","parts":["Chào ",["baby","bé con",0],"! Mẹ thiên nhiên cho con một ",["nest","tổ",1]," ấm."]}]},{"n":2,"title":"Bước chân đầu tiên","minutes":5,"optional":false,"goal":"Tập đứng, tập đi, theo dấu chân cha trên cỏ.","beats":["Mốc loạng choạng, mỗi câu đúng đi vững thêm một bước.","Bố Gruk bước chậm để dấu chân cha in rõ cho con theo."],"question_hook":"Chạm vào vật thể đang phát sáng trên đồng cỏ (dấu chân, vũng nước, bụi cỏ, quả trứng...) để mở câu hỏi nhỏ ngay cạnh nó; đúng thì khủng long con làm được việc đó (ngửi, vồ, uống, trốn, gầm), sai thì cha nhắc lại sau 5 giây, không trừ điểm nặng. Dấu chân cha sáng dần lên, chạm đúng dấu kế tiếp.","reward":"Mốc đi vững.","vocab":["walk","follow","step","dad","grass"],"assets":["dino_trex_brown","ground_grass_tuft","ground_grass_block","river_grass_tall","river_butterfly","anim_wave"],"subtitles":[{"en":"Dad walks slowly and Moc follows every step.","vi":"Bố bước chậm, Mốc bước theo từng bước chân.","parts":[["Dad","Bố",0]," bước chậm, Mốc ",["follow","bước theo",1]," từng ",["step","bước chân",1],"."]},{"en":"Do not be afraid! It is only grass.","vi":"Đừng sợ! Cỏ cao chỉ cỏ thôi.","parts":["Đừng sợ! Cỏ cao chỉ ",["grass","cỏ",0]," thôi."]}]},{"n":3,"title":"Gặp bầy nhỏ","minutes":5,"optional":false,"goal":"Gọi tên các bạn cùng bầy: Sừng, Gai, Chân Dài.","beats":["Mỗi bạn có một đặc điểm; gọi đúng thì bạn chạy tới chơi cùng.","Cô Đuôi Dài dạy cách chào bằng cái chạm mũi."],"question_hook":"Chạm vào vật thể đang phát sáng trên đồng cỏ (dấu chân, vũng nước, bụi cỏ, quả trứng...) để mở câu hỏi nhỏ ngay cạnh nó; đúng thì khủng long con làm được việc đó (ngửi, vồ, uống, trốn, gầm), sai thì cha nhắc lại sau 5 giây, không trừ điểm nặng. Mỗi bạn nhỏ là một thẻ từ: nối đúng tên và đặc điểm.","reward":"Ba bạn mới.","vocab":["friend","horn","tail","big","small"],"assets":["dino_triceratops","dino_stegosaurus","ground_clearing","tree_x01","tree_x02","anim_cheer"],"subtitles":[{"en":"This is a new friend with a big horn.","vi":"Đây là bạn mới: cậu ấy có một cái sừng to.","parts":["Đây là ",["friend","bạn",0]," mới: cậu ấy có một cái ",["horn","sừng",2]," ",["big","to",0],"."]},{"en":"That one has a small tail full of spikes.","vi":"Cậu kia thì có cái đuôi đầy gai nhỏ.","parts":["Cậu kia thì có cái ",["tail","đuôi",1]," đầy gai ",["small","nhỏ",0],"."]}]},{"n":4,"title":"Uống nước lần đầu","minutes":5,"optional":false,"goal":"Tới hồ nước, nhận biết nước sạch và nước đục.","beats":["Cô Đuôi Dài chỉ nước trong, nước đục nổi bọt thì tránh.","Mốc cúi đầu uống từng ngụm nhỏ, cả bầy canh xung quanh."],"question_hook":"Chạm vào vật thể đang phát sáng trên đồng cỏ (dấu chân, vũng nước, bụi cỏ, quả trứng...) để mở câu hỏi nhỏ ngay cạnh nó; đúng thì khủng long con làm được việc đó (ngửi, vồ, uống, trốn, gầm), sai thì cha nhắc lại sau 5 giây, không trừ điểm nặng. Vũng nước nào đúng thì sáng xanh.","reward":"Mốc biết chọn nước.","vocab":["water","drink","clean","muddy","lake"],"assets":["mini_azure_river","river_lilypad","river_reed","palm_a","palm_b","river_pebbles"],"subtitles":[{"en":"The water is clean, drink up, little one!","vi":"Nước sạch trong vắt, uống đi con!","parts":["Nước ",["clean","sạch",1]," trong vắt, ",["drink","uống",0]," đi con!"]},{"en":"This one is muddy, do not drink it.","vi":"Còn vũng này đục lắm, đừng uống.","parts":["Còn vũng này ",["muddy","đục",2]," lắm, đừng ",["drink","uống",0],"."]}]},{"n":5,"title":"Tiếng gầm báo động","minutes":5,"optional":false,"goal":"Phân biệt tiếng gầm vui, gọi bầy và báo nguy.","beats":["Ba tiếng gầm khác nhau vang lên từ vách đá; nghe đúng thì Mốc phản ứng đúng.","Một bóng tối lướt qua trên cao, hóa ra là con chim lớn."],"question_hook":"Chạm vào vật thể đang phát sáng trên đồng cỏ (dấu chân, vũng nước, bụi cỏ, quả trứng...) để mở câu hỏi nhỏ ngay cạnh nó; đúng thì khủng long con làm được việc đó (ngửi, vồ, uống, trốn, gầm), sai thì cha nhắc lại sau 5 giây, không trừ điểm nặng. Mỗi tiếng gầm là một câu nghe, chọn đúng ý nghĩa của nó.","reward":"Mốc biết nghe báo động.","vocab":["roar","danger","listen","safe","run"],"assets":["river_cliff","river_rock_large","river_rock_medium","river_birds","tree_x03","tree_x04"],"subtitles":[{"en":"Listen! This roar means danger.","vi":"Nghe! Tiếng gầm này nghĩa là nguy hiểm.","parts":[["Listen","Nghe",1],"! Tiếng gầm này nghĩa là ",["danger","nguy hiểm",2],"."]},{"en":"Everyone run to a safe place!","vi":"Mọi người chạy về chỗ an toàn nào!","parts":["Mọi người ",["run","chạy",0]," về chỗ ",["safe","an toàn",1]," nào!"]}]},{"n":6,"title":"Chạy về tổ trước hoàng hôn","minutes":5,"optional":false,"goal":"Một mình chạy về tổ qua bãi cỏ khi trời sắp tối.","beats":["Đường chạy thẳng băng, mỗi câu đúng tăng tốc, sai thì vấp nhẹ.","Bố Gruk đứng ở cuối đường và gọi tên Mốc lần đầu."],"question_hook":"Chạm vào vật thể đang phát sáng trên đồng cỏ (dấu chân, vũng nước, bụi cỏ, quả trứng...) để mở câu hỏi nhỏ ngay cạnh nó; đúng thì khủng long con làm được việc đó (ngửi, vồ, uống, trốn, gầm), sai thì cha nhắc lại sau 5 giây, không trừ điểm nặng. Ba đoạn đường, mỗi đoạn một câu; đúng cả ba thì về kịp.","reward":"Tên Mốc và huy hiệu \"Bước Chạy Đầu\".","vocab":["home","night","fast","name","proud"],"assets":["ground_strip_6x20","ground_grass_iso","tree_x05","tree_x06_duo","dino_nest_shelter","hdri_sunset"],"subtitles":[{"en":"It is getting dark, run home fast!","vi":"Trời sắp tối, chạy nhanh về nhà thôi!","parts":["Trời sắp tối, chạy ",["fast","nhanh",1]," về ",["home","nhà",0]," thôi!"]},{"en":"\"Moc!\" Dad calls his name. He is so proud.","vi":"\"Mốc!\" Cha gọi tên con. Cha thật tự hào.","parts":["\"",["Moc","Mốc",0],"!\" Cha gọi tên con. Cha thật ",["proud","tự hào",3],"."]}]},{"n":7,"title":"Chặng phụ: Đếm sao bên ổ","minutes":5,"optional":true,"goal":"Nằm cạnh cha, đếm sao và học các con số.","beats":["Mỗi câu đúng một ngôi sao hiện lên."],"question_hook":"Câu hỏi hiện trên vật thể phát sáng trên đồng cỏ như các chặng chính. Câu khó hơn một bậc, sao nhân đôi.","reward":"Sao đôi.","vocab":["star","count","sleep"],"assets":["tree_pixel","hdri_night"],"subtitles":[{"en":"One, two, three... what stars!","vi":"Một, hai, ba... ngôi sao ơi!","parts":["Một, hai, ba... ",["star","ngôi sao",0]," ơi!"]}]},{"n":8,"title":"Chặng phụ: Nhật ký khủng long con","minutes":5,"optional":true,"goal":"Nói hoặc chọn một câu về ngày đầu tiên của em.","beats":["Dòng nhật ký được khắc lên một tảng đá cạnh ổ."],"question_hook":"Câu viết ngắn, chấm theo tiêu chí, không tính thua.","reward":"Huy hiệu \"Ngày Đầu Đời\".","vocab":["today","happy","first"],"assets":["tree_pixel_stylized"],"subtitles":[{"en":"Today I am very happy.","vi":"Hôm nay con rất vui.","parts":["Hôm nay con rất ",["happy","vui",1],"."]}]}],{},["anim_cheer","anim_wave","dino_antelope","dino_diplodocus","dino_nest_shelter","dino_rabbit","dino_raptor_rider","dino_rat","dino_sauropod_grey","dino_stegosaurus","dino_trex_brown","dino_triceratops","dino_wolf_a","dino_wolf_b","ground_clearing","ground_grass_block","ground_grass_iso","ground_grass_patch","ground_grass_tuft","ground_strip_6x20","hdri_dawn","hdri_night","hdri_sunset","mini_azure_river","mushrooms","palm_a","palm_b","river_birds","river_butterfly","river_cliff","river_grass_tall","river_lilypad","river_pebbles","river_reed","river_rock_large","river_rock_medium","tree_nursery_pot","tree_pixel","tree_pixel_stylized","tree_x01","tree_x02","tree_x03","tree_x04","tree_x05","tree_x06_duo","wood_plank_a"]],["dino-02",2,"Bài Học Săn Mồi","Chương 2 của saga: cha dạy con đọc dấu chân, nằm im trong cỏ, theo gió, vồ mồi và chia mồi cho bầy (nhẹ nhàng, không cảnh đau).","Mốc đã chạy vững, hôm nay Bố Gruk dẫn Mốc ra đồng cỏ xa hơn để học cách tự kiếm ăn. Cha chỉ cho Mốc đọc dấu chân trên bùn: dấu nào của thỏ, của linh dương, của chuột. Rồi hai cha con nằm im trong cỏ, đổi hướng theo gió để mồi không phát hiện. Mỗi lần săn, Mốc phải trả lời đúng mới vồ trúng; sai thì mồi chạy thoát và cha chỉ cười. Săn xong, cha dạy Mốc chia mồi cho cả bầy, kể cả Lông Xù đang đói. Mốc hiểu: săn giỏi không phải để giành phần mình, mà để bầy không ai bị đói.","Đồng cỏ rộng giữa trưa, cỏ cao đến bụng, gió thổi thành từng đợt sóng. Có bãi bùn mềm in dấu chân, lùm cây thưa, vài khối đá lớn làm chỗ nấp.",[{"n":1,"title":"Dấu chân trên bùn","minutes":5,"optional":false,"goal":"Đọc dấu chân và đoán con vật đã đi qua.","beats":["Dấu chân in rõ trên bãi bùn, to nhỏ khác nhau.","Bố Gruk chỉ vết ba ngón, vết hai ngón."],"question_hook":"Chạm vào vật thể đang phát sáng trên đồng cỏ (dấu chân, vũng nước, bụi cỏ, quả trứng...) để mở câu hỏi nhỏ ngay cạnh nó; đúng thì khủng long con làm được việc đó (ngửi, vồ, uống, trốn, gầm), sai thì cha nhắc lại sau 5 giây, không trừ điểm nặng. Mỗi dấu chân là một câu nối đúng tên con vật.","reward":"Mốc đọc được dấu chân.","vocab":["footprint","mud","rabbit","track","small"],"assets":["ground_soil_patch","dino_rabbit","river_pebbles","river_pebbles__alt1","tree_x07_elm","hdri_noon"],"subtitles":[{"en":"Look, a footprint in the mud.","vi":"Nhìn kìa, một dấu chân trên bùn.","parts":["Nhìn kìa, một ",["footprint","dấu chân",2]," trên ",["mud","bùn",2],"."]},{"en":"A small print like this belongs to a rabbit.","vi":"Dấu nhỏ thế này là của một con thỏ.","parts":["Dấu ",["small","nhỏ",0]," thế này là của một con ",["rabbit","thỏ",1],"."]}]},{"n":2,"title":"Nằm im trong cỏ","minutes":5,"optional":false,"goal":"Ẩn mình trong cỏ cao để mồi không thấy.","beats":["Cỏ cao che kín, mỗi câu đúng làm Mốc nằm im thêm một nhịp.","Bố Gruk thì thầm: chỉ thở nhẹ thôi."],"question_hook":"Chạm vào vật thể đang phát sáng trên đồng cỏ (dấu chân, vũng nước, bụi cỏ, quả trứng...) để mở câu hỏi nhỏ ngay cạnh nó; đúng thì khủng long con làm được việc đó (ngửi, vồ, uống, trốn, gầm), sai thì cha nhắc lại sau 5 giây, không trừ điểm nặng. Câu hỏi hiện trong bụi cỏ rung rinh.","reward":"Mốc nấp giỏi.","vocab":["hide","quiet","tall grass","still","breathe"],"assets":["river_grass_tall","ground_grass_dark","dino_antelope","river_bush","river_fern"],"subtitles":[{"en":"Stay still and hide in the tall grass.","vi":"Nằm yên và nấp trong cỏ cao nhé.","parts":["Nằm yên và ",["hide","nấp",1]," trong cỏ cao nhé."]},{"en":"You must be quiet, do not breathe hard.","vi":"Phải thật im lặng, đừng thở mạnh.","parts":["Phải thật ",["quiet","im lặng",1],", đừng ",["breathe","thở",3]," mạnh."]}]},{"n":3,"title":"Theo hướng gió","minutes":5,"optional":false,"goal":"Đổi hướng tiếp cận ngược gió để mồi không ngửi thấy mùi.","beats":["Cánh bướm và lá bay cho biết hướng gió.","Cha đứng đầu hướng gió, con đứng sau."],"question_hook":"Chạm vào vật thể đang phát sáng trên đồng cỏ (dấu chân, vũng nước, bụi cỏ, quả trứng...) để mở câu hỏi nhỏ ngay cạnh nó; đúng thì khủng long con làm được việc đó (ngửi, vồ, uống, trốn, gầm), sai thì cha nhắc lại sau 5 giây, không trừ điểm nặng. Hướng gió là một mũi tên, chọn đúng hướng mới tiến lên.","reward":"Mốc đi ngược gió.","vocab":["wind","left","right","smell","against"],"assets":["tree_x08_verdant","tree_x09_lone","river_butterfly__alt1","dino_rat","ground_grass_emerald"],"subtitles":[{"en":"The wind blows from left to right.","vi":"Gió thổi từ bên trái sang bên phải.","parts":[["Wind","Gió",1]," thổi từ bên ",["left","trái",0]," sang bên ",["right","phải",0],"."]},{"en":"The prey will smell us if we go the wrong way.","vi":"Mồi sẽ ngửi thấy mùi của ta nếu đi sai hướng.","parts":["Mồi sẽ ngửi thấy ",["smell","mùi",2]," của ta nếu đi sai hướng."]}]},{"n":4,"title":"Cú vồ đầu tiên","minutes":5,"optional":false,"goal":"Vồ trúng con mồi nhỏ đúng thời điểm.","beats":["Thanh nhịp: bấm đúng lúc câu đúng, cú vồ trúng.","Con mồi bị trượt chỉ chạy đi, không có ai đau."],"question_hook":"Chạm vào vật thể đang phát sáng trên đồng cỏ (dấu chân, vũng nước, bụi cỏ, quả trứng...) để mở câu hỏi nhỏ ngay cạnh nó; đúng thì khủng long con làm được việc đó (ngửi, vồ, uống, trốn, gầm), sai thì cha nhắc lại sau 5 giây, không trừ điểm nặng. Câu hỏi hiện ngay trên con mồi trước cú vồ.","reward":"Bữa ăn đầu tiên Mốc tự kiếm.","vocab":["jump","catch","quick","prey","miss"],"assets":["dino_rat","dino_rabbit","ground_grass_iso","ground_grass_block","tree_x10_ancient_a"],"subtitles":[{"en":"Wait... jump! Did you catch it or miss it?","vi":"Chờ đã... nhảy lên! Bắt được rồi hay trượt?","parts":["Chờ đã... ",["jump","nhảy",1]," lên! Bắt được rồi hay ",["miss","trượt",2],"?"]},{"en":"The prey is quick, so you must be accurate.","vi":"Con mồi chạy rất nhanh, phải thật chính xác.","parts":["Con mồi chạy rất ",["quick","nhanh",1],", phải thật chính xác."]}]},{"n":5,"title":"Chia mồi cho bầy","minutes":5,"optional":false,"goal":"Mang mồi về và chia công bằng, kể cả cho Lông Xù.","beats":["Cha chia thành các phần đều nhau và dạy Mốc đếm.","Lông Xù nhìn từ xa, Mốc đem một phần ra cho nó."],"question_hook":"Chạm vào vật thể đang phát sáng trên đồng cỏ (dấu chân, vũng nước, bụi cỏ, quả trứng...) để mở câu hỏi nhỏ ngay cạnh nó; đúng thì khủng long con làm được việc đó (ngửi, vồ, uống, trốn, gầm), sai thì cha nhắc lại sau 5 giây, không trừ điểm nặng. Câu đếm và chia: mỗi phần đúng thì bầy đủ ăn.","reward":"Mốc học chia sẻ.","vocab":["share","half","hungry","enough","together"],"assets":["dino_trex_brown","dino_raptor_rider","dino_wolf_a","river_stump","river_log_fallen"],"subtitles":[{"en":"We share with everyone, even those who are hungry.","vi":"Chúng ta chia sẻ cho mọi người, kể cả bạn đang đói.","parts":["Chúng ta ",["share","chia sẻ",1]," cho mọi người, kể cả bạn đang ",["hungry","đói",1],"."]},{"en":"Give half to that friend.","vi":"Chia một nửa cho bạn ấy nhé.","parts":["Chia ",["half","một nửa",2]," cho bạn ấy nhé."]}]},{"n":6,"title":"Về bầy mang thức ăn","minutes":5,"optional":false,"goal":"Mang thức ăn về, cả bầy cùng ăn và kể chuyện bên tổ.","beats":["Bầy quây tròn, cô Đuôi Dài khen Mốc.","Cha kể lần đầu tiên cha đi săn khi còn nhỏ."],"question_hook":"Chạm vào vật thể đang phát sáng trên đồng cỏ (dấu chân, vũng nước, bụi cỏ, quả trứng...) để mở câu hỏi nhỏ ngay cạnh nó; đúng thì khủng long con làm được việc đó (ngửi, vồ, uống, trốn, gầm), sai thì cha nhắc lại sau 5 giây, không trừ điểm nặng. Câu hỏi hiện trên bữa ăn chung, đúng là bầy được no.","reward":"Huy hiệu \"Thợ Săn Nhỏ\".","vocab":["dinner","family","story","proud","full"],"assets":["dino_diplodocus","dino_sauropod_grey","ground_stone_floor","tree_x11_ancient_b","fx_fire","hdri_sunset"],"subtitles":[{"en":"The whole family eats dinner together.","vi":"Cả gia đình cùng ăn bữa tối.","parts":["Cả ",["family","gia đình",1]," cùng ăn ",["dinner","bữa tối",1],"."]},{"en":"Dad tells an old story and everyone is full.","vi":"Cha kể một câu chuyện xưa, ai cũng no bụng.","parts":["Cha kể một ",["story","câu chuyện",1]," xưa, ai cũng no bụng."]}]},{"n":7,"title":"Chặng phụ: Nấm lạ","minutes":5,"optional":true,"goal":"Phân biệt nấm ăn được và nấm không ăn.","beats":["Cô Đuôi Dài dạy nhìn màu và mùi, cái gì lạ thì không ăn."],"question_hook":"Câu hỏi hiện trên vật thể phát sáng trên đồng cỏ như các chặng chính. Câu khó hơn một bậc, sao nhân đôi.","reward":"Sao đôi.","vocab":["mushroom","safe","poison"],"assets":["mushrooms","river_moss_rock"],"subtitles":[{"en":"This red mushroom may be poisonous.","vi":"Cây nấm đỏ này có thể độc.","parts":["Cây ",["mushroom","nấm",2]," đỏ này có thể ",["poison","độc",4],"."]}]},{"n":8,"title":"Chặng phụ: Nhật ký săn","minutes":5,"optional":true,"goal":"Nói hoặc chọn một câu về điều em học được.","beats":["Dòng nhật ký được khắc lên một tảng đá."],"question_hook":"Câu viết ngắn, chấm theo tiêu chí, không tính thua.","reward":"Huy hiệu \"Bài Học Đầu Tay\".","vocab":["learn","today","share"],"assets":["river_sign"],"subtitles":[{"en":"Today I learned how to share.","vi":"Hôm nay con học được cách chia sẻ.","parts":["Hôm nay con ",["learn","học được",1]," cách chia sẻ."]}]}],{},["dino_antelope","dino_diplodocus","dino_rabbit","dino_raptor_rider","dino_rat","dino_sauropod_grey","dino_stegosaurus","dino_trex_brown","dino_triceratops","dino_wolf_a","dino_wolf_b","fx_fire","ground_grass_block","ground_grass_dark","ground_grass_emerald","ground_grass_iso","ground_soil_patch","ground_stone_floor","hdri_noon","hdri_sunset","mushrooms","river_bush","river_butterfly__alt1","river_fern","river_grass_tall","river_log_fallen","river_moss_rock","river_pebbles","river_pebbles__alt1","river_sign","river_stump","tree_x07_elm","tree_x08_verdant","tree_x09_lone","tree_x10_ancient_a","tree_x11_ancient_b"]],["dino-03",3,"Đường Dài Tới Hồ Nước","Chương 3 của saga: hạn hán, cả bầy đi qua cao nguyên khô và rừng nấm tìm hồ nước thật; cha và cô Đuôi Dài dạy tìm nước, tiết kiệm sức, đi cùng nhau.","Mùa khô kéo dài, vũng nước của bầy cạn dần. Ông Cổ Dài nhớ có một hồ lớn sau cao nguyên và dẫn cả bầy đi. Đường dài, nắng gắt; Mốc học cách đi theo đội hình, nghỉ dưới bóng đá, tìm nước bằng cách nhìn chim bay và nghe tiếng gió. Qua rừng nấm, thác nước chặn đường, cả bầy phải xếp hàng đi qua từng bậc đá. Cuối cùng hồ nước hiện ra, nhưng cha dặn: uống từng chút, nhường người già và bé nhỏ trước. Mốc nhìn thấy cha uống sau cùng, dù cha mệt nhất.","Cao nguyên đỏ khô cằn, đất nứt nẻ, vài bụi cây gầy. Rồi rừng nấm khổng lồ, thác nước lấp lánh, và cuối đường là hồ xanh có đảo nổi giữa hồ.",[{"n":1,"title":"Cao nguyên khô","minutes":5,"optional":false,"goal":"Nhận ra dấu hiệu hạn hán và quyết định lên đường.","beats":["Đất nứt thành mảng, bụi bay, cỏ vàng úa.","Ông Cổ Dài kể về hồ nước xưa.","Đụn cát nóng nằm rải rác trên cao nguyên khô: gọi đúng tên thì cát lún nông cho cả bầy đi qua."],"question_hook":"Chạm vào vật thể đang phát sáng trên đồng cỏ (dấu chân, vũng nước, bụi cỏ, quả trứng...) để mở câu hỏi nhỏ ngay cạnh nó; đúng thì khủng long con làm được việc đó (ngửi, vồ, uống, trốn, gầm), sai thì cha nhắc lại sau 5 giây, không trừ điểm nặng. Mỗi vết nứt là một câu về thời tiết và nước.","reward":"Bầy xuất phát.","vocab":["dry","hot","thirsty","plateau","leave","sand","dust"],"assets":["dino_world_dry_plateau","river_cliff__alt1","ground_stone_floor","dino_sauropod_grey","hdri_noon","dino_sand","dino_sand_2"],"subtitles":[{"en":"The sky is hot and the ground is dry and cracked.","vi":"Trời nóng và đất khô nứt nẻ.","parts":["Trời ",["hot","nóng",1]," và đất ",["dry","khô",1]," nứt nẻ."]},{"en":"We must leave to find water. Everyone is thirsty.","vi":"Chúng ta phải rời đi để tìm nước. Ai cũng đang khát.","parts":["Chúng ta phải ",["leave","rời đi",2]," để tìm nước. Ai cũng đang ",["thirsty","khát",2],"."]}]},{"n":2,"title":"Đi theo đội hình","minutes":5,"optional":false,"goal":"Cả bầy đi thành hàng: lớn trước, nhỏ giữa, già cuối.","beats":["Mỗi nhóm giữ khoảng cách vừa đủ, không ai bị bỏ lại.","Tia Chớp chạy đi chạy lại báo tin cho cả hàng.","Dấu chân của cha in sâu trên cát: đọc đúng từ thì đàn con đặt chân vào đúng dấu mà đi theo."],"question_hook":"Chạm vào vật thể đang phát sáng trên đồng cỏ (dấu chân, vũng nước, bụi cỏ, quả trứng...) để mở câu hỏi nhỏ ngay cạnh nó; đúng thì khủng long con làm được việc đó (ngửi, vồ, uống, trốn, gầm), sai thì cha nhắc lại sau 5 giây, không trừ điểm nặng. Câu hỏi hiện trên lưng khủng long đi trước; đúng thì hàng gọn.","reward":"Bầy đi nhanh hơn.","vocab":["line","front","behind","together","stay","footprint","follow"],"assets":["dino_raptor_rider","dino_triceratops","dino_stegosaurus","river_rock_small","river_rock_medium","dino_footprint"],"subtitles":[{"en":"Stay in line, do not fall behind.","vi":"Ở lại trong hàng, đừng tụt lại phía sau.","parts":[["Stay","Ở lại",1]," trong hàng, đừng tụt lại ",["behind","phía sau",2],"."]},{"en":"We walk together.","vi":"Chúng ta đi cùng nhau.","parts":["Chúng ta đi ",["together","cùng nhau",1],"."]}]},{"n":3,"title":"Rừng nấm khổng lồ","minutes":5,"optional":false,"goal":"Đi qua rừng nấm, nghỉ dưới bóng râm, tìm lối ra.","beats":["Nấm to che nắng, nhưng đường rẽ nhiều nhánh.","Cô Đuôi Dài dạy đánh dấu đường bằng cành cây."],"question_hook":"Chạm vào vật thể đang phát sáng trên đồng cỏ (dấu chân, vũng nước, bụi cỏ, quả trứng...) để mở câu hỏi nhỏ ngay cạnh nó; đúng thì khủng long con làm được việc đó (ngửi, vồ, uống, trốn, gầm), sai thì cha nhắc lại sau 5 giây, không trừ điểm nặng. Mỗi ngã rẽ là một câu hỏi chỉ đường.","reward":"Cả bầy nghỉ lấy sức.","vocab":["shade","rest","path","turn","giant"],"assets":["mushrooms","tree_x09_lone","tree_x10_ancient_a","tree_x12_dark_bark","river_fern__alt1"],"subtitles":[{"en":"We can rest a little in this shade.","vi":"Dưới bóng râm này ta có thể nghỉ một chút.","parts":["Dưới ",["shade","bóng râm",3]," này ta có thể ",["rest","nghỉ",1]," một chút."]},{"en":"Choose the right path and turn.","vi":"Chọn đúng lối đi rồi rẽ nhé.","parts":["Chọn đúng ",["path","lối đi",2]," rồi ",["turn","rẽ",1]," nhé."]}]},{"n":4,"title":"Thác nước chắn lối","minutes":5,"optional":false,"goal":"Leo qua từng bậc đá cạnh thác, giúp nhau qua.","beats":["Thác đổ mát lạnh, bậc đá trơn.","Khủng long lớn đưa đuôi làm cầu cho bạn nhỏ."],"question_hook":"Chạm vào vật thể đang phát sáng trên đồng cỏ (dấu chân, vũng nước, bụi cỏ, quả trứng...) để mở câu hỏi nhỏ ngay cạnh nó; đúng thì khủng long con làm được việc đó (ngửi, vồ, uống, trốn, gầm), sai thì cha nhắc lại sau 5 giây, không trừ điểm nặng. Mỗi bậc đá là một câu; đúng thì bậc đá chắc.","reward":"Cả bầy qua thác.","vocab":["waterfall","climb","slippery","help","bridge"],"assets":["mini_runestone_falls","river_waterfall","river_waterfall_pool","river_moss_rock","wood_plank_b"],"subtitles":[{"en":"The waterfall is strong and the rocks are slippery.","vi":"Thác nước chảy rất mạnh, đá thì trơn.","parts":[["Waterfall","Thác nước",2]," chảy rất mạnh, đá thì ",["slippery","trơn",4],"."]},{"en":"Help each other climb across.","vi":"Hãy giúp nhau leo qua.","parts":["Hãy ",["help","giúp",1]," nhau ",["climb","leo",2]," qua."]}]},{"n":5,"title":"Hồ nước hiện ra","minutes":5,"optional":false,"goal":"Tìm thấy hồ, canh chừng và uống theo thứ tự.","beats":["Mặt hồ phẳng như gương, có đảo nổi ở giữa.","Cha dặn nhường người già và bé nhỏ uống trước."],"question_hook":"Chạm vào vật thể đang phát sáng trên đồng cỏ (dấu chân, vũng nước, bụi cỏ, quả trứng...) để mở câu hỏi nhỏ ngay cạnh nó; đúng thì khủng long con làm được việc đó (ngửi, vồ, uống, trốn, gầm), sai thì cha nhắc lại sau 5 giây, không trừ điểm nặng. Vũng nước nào an toàn thì sáng xanh.","reward":"Cả bầy có nước.","vocab":["lake","drink","first","old","careful"],"assets":["mini_jungle_river","mini_floating_oasis","river_lilypad__alt1","palm_a","palm_b"],"subtitles":[{"en":"There is the lake! But be careful when drinking.","vi":"Hồ kia rồi! Nhưng hãy cẩn thận khi uống.","parts":[["Lake","Hồ",1]," kia rồi! Nhưng hãy cẩn thận khi ",["drink","uống",0],"."]},{"en":"The old and the little ones drink first.","vi":"Người già và bé nhỏ uống trước.","parts":["Người già và bé nhỏ uống ",["first","trước",1],"."]}]},{"n":6,"title":"Cha uống sau cùng","minutes":5,"optional":false,"goal":"Cả bầy nghỉ bên hồ; Mốc thấy cha mệt nhưng vẫn nhường.","beats":["Cha ngồi xuống, thở dài, nhìn con cười.","Ông Cổ Dài kể: một bầy mạnh khi biết nhường nhau."],"question_hook":"Chạm vào vật thể đang phát sáng trên đồng cỏ (dấu chân, vũng nước, bụi cỏ, quả trứng...) để mở câu hỏi nhỏ ngay cạnh nó; đúng thì khủng long con làm được việc đó (ngửi, vồ, uống, trốn, gầm), sai thì cha nhắc lại sau 5 giây, không trừ điểm nặng. Câu hỏi hiện trên mặt hồ; đúng là sóng lăn tăn.","reward":"Huy hiệu \"Cả Bầy Đến Nơi\".","vocab":["tired","thank","strong","family","rest"],"assets":["dino_trex_brown","dino_diplodocus","river_driftwood","river_birds","hdri_sunset"],"subtitles":[{"en":"Dad is very tired but still smiling.","vi":"Cha mệt lắm, nhưng cha vẫn mỉm cười.","parts":["Cha ",["tired","mệt",1]," lắm, nhưng cha vẫn mỉm cười."]},{"en":"Thank you, Dad, thank you so much.","vi":"Cảm ơn cha, cảm ơn cha rất nhiều.","parts":["Cảm ơn cha, ",["thank","cảm ơn",0]," cha rất nhiều."]}]},{"n":7,"title":"Chặng phụ: Đảo nổi giữa hồ","minutes":5,"optional":true,"goal":"Ngắm đảo nổi và học từ chỉ vị trí.","beats":["Đảo nổi xa xa, bay lơ lửng."],"question_hook":"Câu hỏi hiện trên vật thể phát sáng trên đồng cỏ như các chặng chính. Câu khó hơn một bậc, sao nhân đôi.","reward":"Sao đôi.","vocab":["island","above","near"],"assets":["mini_floating_waterfall"],"subtitles":[{"en":"That island floats above the lake.","vi":"Hòn đảo kia bay trên mặt hồ.","parts":["Hòn ",["island","đảo",2]," kia bay trên mặt ",["lake","hồ",1],"."]}]},{"n":8,"title":"Chặng phụ: Nhật ký đường dài","minutes":5,"optional":true,"goal":"Nói hoặc chọn một câu về chuyến đi.","beats":["Dòng nhật ký khắc lên thân gỗ trôi."],"question_hook":"Câu viết ngắn, chấm theo tiêu chí, không tính thua.","reward":"Huy hiệu \"Người Đi Xa\".","vocab":["long","walk","tired"],"assets":["wood_plank_a"],"subtitles":[{"en":"Today I walked very far.","vi":"Hôm nay con đã đi bộ rất xa.","parts":["Hôm nay con đã ",["walk","đi bộ",1]," rất ",["long","xa",1],"."]}]}],{},["dino_antelope","dino_diplodocus","dino_footprint","dino_rabbit","dino_raptor_rider","dino_sand","dino_sand_2","dino_sauropod_grey","dino_stegosaurus","dino_trex_brown","dino_triceratops","dino_wolf_a","dino_wolf_b","dino_world_dry_plateau","ground_stone_floor","hdri_noon","hdri_sunset","mini_floating_oasis","mini_floating_waterfall","mini_jungle_river","mini_runestone_falls","mushrooms","palm_a","palm_b","river_birds","river_cliff__alt1","river_driftwood","river_fern__alt1","river_lilypad__alt1","river_moss_rock","river_rock_medium","river_rock_small","river_waterfall","river_waterfall_pool","tree_x09_lone","tree_x10_ancient_a","tree_x12_dark_bark","wood_plank_a","wood_plank_b"]],["dino-04",4,"Đêm Bão Và Tổ Ấm","Chương 4 của saga: bão đêm, cả bầy tìm chỗ trú, đối mặt sói đói, sưởi ấm bên nhau; Mốc thấy cha bắt đầu yếu đi.","Chiều xuống, bầu trời đổi màu; Ông Cổ Dài ngửi thấy mùi bão. Cả bầy phải kịp tìm chỗ trú trước khi trời tối hẳn. Mốc giúp khuân ván gỗ gia cố túp da cổ, chỉ chỗ gió lùa, đếm đủ cả bầy bên trong. Đêm xuống, lũ sói đói lảng vảng quanh chỗ trú; cô Đuôi Dài dạy bầy đứng sát nhau, cha đứng chắn cửa. Sấm sét làm một cây đổ gần lối vào, cả bầy phải làm việc cùng nhau để dọn lối. Sáng ra, mưa tạnh, Mốc nhận thấy cha đứng chậm hơn trước và hơi thở nặng hơn.","Bờ hồ lúc chạng vạng, mây đen cuồn cuộn, gió giật; có túp da cổ làm chỗ trú, rừng cây cổ thụ và thân gỗ đổ. Sấm chớp xa, mưa rơi từng đợt.",[{"n":1,"title":"Mây đen kéo tới","minutes":5,"optional":false,"goal":"Nhận biết dấu hiệu bão và báo cho cả bầy.","beats":["Gió đổi hướng, chim bay thấp, mây đen dày.","Ông Cổ Dài ngửi không khí và lắc đầu."],"question_hook":"Chạm vào vật thể đang phát sáng trên đồng cỏ (dấu chân, vũng nước, bụi cỏ, quả trứng...) để mở câu hỏi nhỏ ngay cạnh nó; đúng thì khủng long con làm được việc đó (ngửi, vồ, uống, trốn, gầm), sai thì cha nhắc lại sau 5 giây, không trừ điểm nặng. Mỗi dấu hiệu là một câu về thời tiết.","reward":"Cả bầy kịp báo động.","vocab":["storm","cloud","wind","cold","warn"],"assets":["tree_x11_ancient_b","dino_sauropod_grey","river_birds","hdri_cloudy"],"subtitles":[{"en":"A storm is coming and clouds cover the sky.","vi":"Bão sắp tới, mây đen kín trời.","parts":[["Storm","Bão",2]," sắp tới, ",["cloud","mây",1]," đen kín trời."]},{"en":"Let everyone warn each other.","vi":"Mọi người hãy báo cho nhau biết nhé.","parts":["Mọi người hãy ",["warn","báo",4]," cho nhau biết nhé."]}]},{"n":2,"title":"Tìm chỗ trú","minutes":5,"optional":false,"goal":"Dẫn cả bầy vào túp da cổ và gia cố mái.","beats":["Ván gỗ ghép thành mái, dây thừng buộc chặt.","Mốc đếm đủ cả bầy vào trong."],"question_hook":"Chạm vào vật thể đang phát sáng trên đồng cỏ (dấu chân, vũng nước, bụi cỏ, quả trứng...) để mở câu hỏi nhỏ ngay cạnh nó; đúng thì khủng long con làm được việc đó (ngửi, vồ, uống, trốn, gầm), sai thì cha nhắc lại sau 5 giây, không trừ điểm nặng. Mỗi tấm ván là một câu; đúng thì ván được chèn vào đúng chỗ.","reward":"Chỗ trú chắc chắn.","vocab":["shelter","roof","inside","strong","count"],"assets":["dino_nest_shelter","wood_plank_b","wood_plank_a","camp_rope","tree_x04","anim_kneel_work"],"subtitles":[{"en":"Quick, get into the shelter, it is going to rain!","vi":"Mau vào chỗ trú, trời sắp mưa!","parts":["Mau vào ",["shelter","chỗ trú",2],", trời sắp mưa!"]},{"en":"The roof must be strong. Let us count if everyone is here.","vi":"Mái nhà phải thật chắc. Ta cùng đếm xem đủ chưa.","parts":["Mái nhà phải thật ",["strong","chắc",1],". Ta cùng ",["count","đếm",0]," xem đủ chưa."]}]},{"n":3,"title":"Sói rình ngoài cửa","minutes":5,"optional":false,"goal":"Giữ bình tĩnh khi sói xuất hiện quanh chỗ trú.","beats":["Những cặp mắt vàng phát sáng ngoài bóng tối.","Cô Đuôi Dài dặn cả bầy đứng sát nhau, không ai chạy ra."],"question_hook":"Chạm vào vật thể đang phát sáng trên đồng cỏ (dấu chân, vũng nước, bụi cỏ, quả trứng...) để mở câu hỏi nhỏ ngay cạnh nó; đúng thì khủng long con làm được việc đó (ngửi, vồ, uống, trốn, gầm), sai thì cha nhắc lại sau 5 giây, không trừ điểm nặng. Hành động đúng là sáng lên: đứng im, đứng sát, hay gọi cha.","reward":"Bầy an toàn.","vocab":["wolf","close","stay","brave","dark"],"assets":["dino_wolf_a","dino_wolf_b","ground_grass_dark","river_bush__alt2","hdri_night"],"subtitles":[{"en":"There are two wolves out there and it is dark.","vi":"Có hai con sói ngoài kia, trời lại tối.","parts":["Có hai con ",["wolf","sói",1]," ngoài kia, trời lại ",["dark","tối",1],"."]},{"en":"Stay together and be brave.","vi":"Hãy ở yên bên nhau và thật dũng cảm.","parts":["Hãy ",["stay","ở yên",1]," bên nhau và thật ",["brave","dũng cảm",3],"."]}]},{"n":4,"title":"Sưởi ấm bên nhau","minutes":5,"optional":false,"goal":"Dựa vào nhau giữ ấm, kể chuyện đợi bão qua.","beats":["Cả bầy xích lại, đứa lớn che đứa nhỏ.","Ông Cổ Dài kể chuyện về lần bão lớn xưa."],"question_hook":"Chạm vào vật thể đang phát sáng trên đồng cỏ (dấu chân, vũng nước, bụi cỏ, quả trứng...) để mở câu hỏi nhỏ ngay cạnh nó; đúng thì khủng long con làm được việc đó (ngửi, vồ, uống, trốn, gầm), sai thì cha nhắc lại sau 5 giây, không trừ điểm nặng. Câu hỏi hiện trên đống lửa nhỏ trong chỗ trú.","reward":"Cả bầy ấm áp.","vocab":["warm","together","story","sleep","cold"],"assets":["dino_stegosaurus","dino_triceratops","fx_fire","fx_smoke","river_woodpile"],"subtitles":[{"en":"The night is cold, but together we are warm.","vi":"Đêm lạnh, nhưng khi ở bên nhau thì rất ấm.","parts":["Đêm ",["cold","lạnh",1],", nhưng khi ở bên nhau thì rất ",["warm","ấm",1],"."]},{"en":"Grandpa tells a story so the children can sleep.","vi":"Cụ kể một câu chuyện cho các cháu ngủ.","parts":["Cụ kể một ",["story","câu chuyện",1]," cho các cháu ",["sleep","ngủ",0],"."]}]},{"n":5,"title":"Sấm sét và cây đổ","minutes":5,"optional":false,"goal":"Cùng nhau dọn cây đổ chắn lối vào.","beats":["Một tia sét đánh gần, thân cây đổ chắn cửa.","Khủng long lớn đẩy, khủng long nhỏ kéo dây."],"question_hook":"Chạm vào vật thể đang phát sáng trên đồng cỏ (dấu chân, vũng nước, bụi cỏ, quả trứng...) để mở câu hỏi nhỏ ngay cạnh nó; đúng thì khủng long con làm được việc đó (ngửi, vồ, uống, trốn, gầm), sai thì cha nhắc lại sau 5 giây, không trừ điểm nặng. Mỗi lần đẩy là một câu; đúng cả nhóm thì thân cây nhúc nhích.","reward":"Lối vào được mở.","vocab":["thunder","push","pull","tree","together"],"assets":["tree_x12_dark_bark","river_driftwood","river_log_fallen","camp_rope","dino_trex_brown"],"subtitles":[{"en":"Thunder cracked and a tree fell across the door.","vi":"Sấm đánh một tiếng, cây cây đổ chắn cửa.","parts":[["Thunder","Sấm",2]," đánh một tiếng, cây ",["tree","cây",0]," đổ chắn cửa."]},{"en":"Everybody push and pull!","vi":"Mọi người cùng đẩy và kéo!","parts":["Mọi người cùng ",["push","đẩy",1]," và ",["pull","kéo",1],"!"]}]},{"n":6,"title":"Bình minh sau bão","minutes":5,"optional":false,"goal":"Mưa tạnh, cả bầy bước ra; Mốc thấy cha mệt hơn.","beats":["Cầu vồng bắc ngang thác nước.","Cha đứng chậm lại, thở nặng nhưng vẫn cười với con."],"question_hook":"Chạm vào vật thể đang phát sáng trên đồng cỏ (dấu chân, vũng nước, bụi cỏ, quả trứng...) để mở câu hỏi nhỏ ngay cạnh nó; đúng thì khủng long con làm được việc đó (ngửi, vồ, uống, trốn, gầm), sai thì cha nhắc lại sau 5 giây, không trừ điểm nặng. Câu hỏi hiện trên cầu vồng; đúng là cầu vồng sáng thêm màu.","reward":"Huy hiệu \"Sống Sót Qua Bão\".","vocab":["rainbow","morning","tired","worry","hope"],"assets":["river_waterfall","river_waterfall_pool","dino_diplodocus","ground_grass_emerald","hdri_dawn"],"subtitles":[{"en":"There is a rainbow after the storm!","vi":"Có một chiếc cầu vồng sau cơn bão!","parts":["Có một chiếc ",["rainbow","cầu vồng",2]," sau cơn bão!"]},{"en":"Dad looks tired. Moc starts to worry.","vi":"Cha trông mệt. Mốc bắt đầu thấy lo lắng.","parts":["Cha trông ",["tired","mệt",1],". Mốc bắt đầu thấy ",["worry","lo lắng",4],"."]}]},{"n":7,"title":"Chặng phụ: Đếm tiếng sấm","minutes":5,"optional":true,"goal":"Đếm giữa chớp và sấm để đoán bão xa hay gần.","beats":["Mỗi tiếng đếm đúng là một vòng nước tỏa ra."],"question_hook":"Câu hỏi hiện trên vật thể phát sáng trên đồng cỏ như các chặng chính. Câu khó hơn một bậc, sao nhân đôi.","reward":"Sao đôi.","vocab":["count","far","near"],"assets":["tree_x08_verdant"],"subtitles":[{"en":"Is the storm still far or already near?","vi":"Bão còn xa hay đã gần?","parts":["Bão còn ",["far","xa",1]," hay đã ",["near","gần",1],"?"]}]},{"n":8,"title":"Chặng phụ: Nhật ký đêm bão","minutes":5,"optional":true,"goal":"Nói hoặc chọn một câu về đêm bão.","beats":["Dòng nhật ký khắc lên vách túp da."],"question_hook":"Câu viết ngắn, chấm theo tiêu chí, không tính thua.","reward":"Huy hiệu \"Đêm Bão\".","vocab":["night","storm","safe"],"assets":["river_sign"],"subtitles":[{"en":"Tonight I feel safe with the herd.","vi":"Đêm nay con thấy an toàn bên bầy.","parts":["Đêm nay con thấy ",["safe","an toàn",1]," bên bầy."]}]}],{},["anim_kneel_work","camp_rope","dino_antelope","dino_diplodocus","dino_nest_shelter","dino_rabbit","dino_raptor_rider","dino_rat","dino_sauropod_grey","dino_stegosaurus","dino_trex_brown","dino_triceratops","dino_wolf_a","dino_wolf_b","fx_fire","fx_smoke","ground_grass_dark","ground_grass_emerald","hdri_cloudy","hdri_dawn","hdri_night","river_birds","river_bush__alt2","river_driftwood","river_log_fallen","river_sign","river_waterfall","river_waterfall_pool","river_woodpile","tree_x04","tree_x08_verdant","tree_x11_ancient_b","tree_x12_dark_bark","wood_plank_a","wood_plank_b"]],["dino-05",5,"Cha Già Và Ngày Đứng Lên","Chương cuối của saga: cha đã già, bị các khủng long khác bắt nạt khi đi uống nước; Mốc đã lớn đứng lên, gọi cả bầy cùng giải cứu cha.","Mùa nước đã qua, Mốc đã lớn gần bằng nửa cha. Bố Gruk bây giờ đi chậm, lưng còng, không còn là kẻ săn nhanh nhất. Một chiều, cha ra hồ uống nước một mình thì bị Răng Vàng và Bóng Đêm chặn đường, xô đẩy và giành chỗ uống. Tia Chớp chạy về báo tin; Mốc khựng lại, nhớ những bài học: đọc dấu chân, nghe báo động, đứng sát nhau, nhường người già. Mốc không lao vào một mình. Mốc gọi cả bầy: cô Đuôi Dài, ông Cổ Dài, Sừng Nhỏ, Gai Gai... mỗi người một việc. Cả bầy đứng thành một hàng chắn, gầm vang cùng lúc; hai kẻ bắt nạt lùi lại, bỏ đi. Cha ngước nhìn con, nói: \"Con đã lớn rồi.\" Hoàng hôn xuống, cha con cùng uống nước bên nhau, cả bầy đứng quanh.","Hồ nước lúc chiều tà, vầng mặt trời đỏ chạm cao nguyên. Gần hồ là bãi đá và đảo rừng nổi lơ lửng, nơi bầy khủng long lạ hay tụ họp. Cỏ vàng rực trong nắng.",[{"n":1,"title":"Cha chậm bước","minutes":5,"optional":false,"goal":"Nhận ra cha đã già: đi chậm, uống chậm, hay nghỉ.","beats":["Mốc đi cạnh cha, chậm lại cho vừa nhịp.","Ông Cổ Dài nói: già không phải yếu, chỉ cần người bên cạnh.","Cha chậm bước, dấu chân in nông; Mốc vẫy cha lại gần và đi chậm cho vừa nhịp."],"question_hook":"Chạm vào vật thể đang phát sáng trên đồng cỏ (dấu chân, vũng nước, bụi cỏ, quả trứng...) để mở câu hỏi nhỏ ngay cạnh nó; đúng thì khủng long con làm được việc đó (ngửi, vồ, uống, trốn, gầm), sai thì cha nhắc lại sau 5 giây, không trừ điểm nặng. Câu hỏi hiện trên dấu chân cha, mỗi dấu chân nặng hơn trước.","reward":"Mốc hiểu cha.","vocab":["old","slow","tired","help","back","footprint","come here"],"assets":["dino_trex_brown","ground_grass_tuft","tree_x01","tree_x03","ground_grass_patch","hdri_noon","dino_footprint","anim_beckon"],"subtitles":[{"en":"Dad is old and walks more slowly than before.","vi":"Cha đã già, bước đi chậm hơn trước.","parts":["Cha đã ",["old","già",0],", bước đi ",["slow","chậm",1]," hơn trước."]},{"en":"Moc says: \"Let me help you, Dad.\"","vi":"Mốc nói: \"Để con giúp cha.\"","parts":["Mốc nói: \"Để con ",["help","giúp",1]," cha.\""]}]},{"n":2,"title":"Hai kẻ bắt nạt","minutes":5,"optional":false,"goal":"Chứng kiến Răng Vàng và Bóng Đêm chặn đường cha ở hồ.","beats":["Hai T-rex lạ gầm gừ, giành chỗ uống, xô cha ngã ngồi.","Cha không đánh lại, chỉ lùi lại để tránh va chạm."],"question_hook":"Chạm vào vật thể đang phát sáng trên đồng cỏ (dấu chân, vũng nước, bụi cỏ, quả trứng...) để mở câu hỏi nhỏ ngay cạnh nó; đúng thì khủng long con làm được việc đó (ngửi, vồ, uống, trốn, gầm), sai thì cha nhắc lại sau 5 giây, không trừ điểm nặng. Mỗi hành động của kẻ bắt nạt là một câu mô tả; chọn đúng để hiểu chuyện gì đang xảy ra.","reward":"Mốc nhìn rõ sự thật.","vocab":["bully","push","angry","unfair","lake"],"assets":["dino_trex_yellow","dino_trex_black","dino_wolf_a","mini_azure_river","river_rock_large"],"subtitles":[{"en":"Two big dinosaurs push Dad around at the lake.","vi":"Hai con khủng long to xác xô đẩy cha ở bờ hồ.","parts":["Hai con khủng long to xác ",["push","xô đẩy",1]," cha ở bờ hồ."]},{"en":"They bully an old dinosaur. How unfair!","vi":"Họ bắt nạt người già. Thật bất công!","parts":["Họ ",["bully","bắt nạt",4]," người già. Thật ",["unfair","bất công",4],"!"]}]},{"n":3,"title":"Mốc dừng lại suy nghĩ","minutes":5,"optional":false,"goal":"Nhớ lại các bài học và lên kế hoạch, không lao vào một mình.","beats":["Mốc nhắm mắt: dấu chân, tiếng gầm, đứng sát nhau, nhường người già.","Mốc quyết định: cần cả bầy."],"question_hook":"Chạm vào vật thể đang phát sáng trên đồng cỏ (dấu chân, vũng nước, bụi cỏ, quả trứng...) để mở câu hỏi nhỏ ngay cạnh nó; đúng thì khủng long con làm được việc đó (ngửi, vồ, uống, trốn, gầm), sai thì cha nhắc lại sau 5 giây, không trừ điểm nặng. Mỗi bài học là một thẻ nhớ; chọn đúng bài học dùng cho tình huống này.","reward":"Một kế hoạch.","vocab":["think","plan","remember","alone","together"],"assets":["mini_logic_island","tree_x05","tree_x06_duo","river_stump","hdri_sunset"],"subtitles":[{"en":"Moc stops to think. He cannot do it alone.","vi":"Mốc dừng lại để suy nghĩ. Một mình thì không thể.","parts":["Mốc dừng lại để ",["think","suy nghĩ",1],". Một mình thì không thể."]},{"en":"I must remember everything Dad taught me and make a plan.","vi":"Con phải nhớ mọi điều cha dạy và có một kế hoạch.","parts":["Con phải ",["remember","nhớ",2]," mọi điều cha dạy và có một ",["plan","kế hoạch",1],"."]}]},{"n":4,"title":"Gọi cả bầy","minutes":5,"optional":false,"goal":"Chạy tới từng thành viên của bầy và kêu gọi họ.","beats":["Tia Chớp chạy trước báo tin; mỗi bạn nhận một việc.","Cô Đuôi Dài, ông Cổ Dài, Sừng Nhỏ, Gai Gai đều đồng ý ngay."],"question_hook":"Chạm vào vật thể đang phát sáng trên đồng cỏ (dấu chân, vũng nước, bụi cỏ, quả trứng...) để mở câu hỏi nhỏ ngay cạnh nó; đúng thì khủng long con làm được việc đó (ngửi, vồ, uống, trốn, gầm), sai thì cha nhắc lại sau 5 giây, không trừ điểm nặng. Mỗi lời gọi là một câu; đúng thì người đó tới.","reward":"Cả bầy có mặt.","vocab":["call","herd","ask","join","ready"],"assets":["dino_raptor_rider","dino_diplodocus","dino_sauropod_grey","dino_triceratops","dino_stegosaurus","anim_cheer"],"subtitles":[{"en":"Moc runs to call the whole herd.","vi":"Mốc chạy đi gọi cả bầy.","parts":["Mốc chạy đi ",["call","gọi",1]," cả ",["herd","bầy",3],"."]},{"en":"\"Are you ready to join me?\"","vi":"\"Các bạn có sẵn sàng tham gia cùng tôi không?\"","parts":["\"Các bạn có ",["ready","sẵn sàng",2]," ",["join","tham gia",3]," cùng tôi không?\""]}]},{"n":5,"title":"Đứng lên","minutes":5,"optional":false,"goal":"Cả bầy xếp hàng tiến về hồ, đứng chắn trước hai kẻ 